import{syncProcessMovie}from './process-player.js?v=20261023-physicscomplete01';
import{tasksForInherit,validInherit,advanceInherit,numericInherit}from './inherit-models.js?v=20261023-physicscomplete01';import{showInherit}from './inherit-visuals.js?v=20261023-physicscomplete01';export{showInherit};
export function mountInherit(l,p,root,{save,done,feedback}){let ts=tasksForInherit(l.widget.slice(8)),w=p.widget;w.inheritTask??=ts[0].id;w.inheritDrafts??={};w.inheritPassed??=[];let i=ts.findIndex(t=>t.id===w.inheritTask);if(i<0)i=0;let t=ts[i],v=w.inheritDrafts[t.id]??={case:0,answer:'',seen:[],step:0},$=s=>root.querySelector(s),remount=()=>mountInherit(l,p,root,{save,done,feedback});p.widgetDone=ts.every(t=>w.inheritPassed.includes(t.id));
syncProcessMovie(l,1,['compare','ledger','evidence','examples','hierarchy','applications'].includes(t.kind)?{process:false}:null);
const field=(id,label,options,value)=>`<label class="field-label" for="${id}">${label}</label><select class="lab-select" id="${id}"><option value="">Choose…</option>${options.map(([a,b])=>`<option value="${a}" ${String(a)===String(value)?'selected':''}>${b}</option>`).join('')}</select>`;
let body='',draw,valid;
if(t.type==='compare'){let c=t.cases[v.case];body=field('inheritCase','Scenario',t.cases.map((c,j)=>[j,c[1]]),v.case)+field('inheritAnswer','Predict and explain',c[2].map((s,j)=>[j,s]),v.answer)+'<button class="secondary" id="revealInherit">Reveal evidence →</button><p id="inheritReadout" aria-live="polite"></p>';draw=()=>{let r=v.revealed===v.case;showInherit(t.kind,{state:c[0],neutral:t.kind==='glands',title:t.title,label:c[1],concealed:!r&&t.kind!=='glands',progress:r?1:0,step:r?5:0});$('#inheritReadout').textContent=r?c[4]:'Predict, then reveal and record.';};valid=()=>v.revealed===v.case&&validInherit(c,v.answer);}
else if(t.type==='sequence'){body=field('inheritNext','Next stage',t.route.map((id,j)=>[id,t.labels[j]]),v.next)+'<button class="secondary" id="advanceInherit">Advance pathway →</button><p id="inheritReadout" aria-live="polite"></p>';draw=()=>{showInherit(t.kind,{title:t.title,progress:v.step/t.route.length,step:v.step,label:v.step+' / '+t.route.length+' stages'});$('#inheritReadout').textContent=v.step?t.labels.slice(0,v.step).join(' → '):'Select the first stage.';};valid=()=>v.step===t.route.length;}
else{body='<p>'+t.prompt+'</p><label class="field-label" for="inheritNumber">Your result / '+(t.unit||'supplied units')+'</label><input class="lab-input" id="inheritNumber" type="number" step="any" value="'+(v.number??'')+'">'+field('inheritReason','Reasoning',t.reasonChoices.map((s,j)=>[j,s]),v.reason);if(t.kind==='graph')body+='<label class="field-label" for="inheritDay">Inspect day</label><input id="inheritDay" type="range" min="1" max="28" value="'+(v.day??14)+'">';draw=()=>showInherit(t.kind,{title:t.title,day:Number(v.day??14),label:'Original illustrative evidence'});valid=()=>numericInherit(v.number,t.answer)&&v.reason!==''&&v.reason!==undefined&&Number(v.reason)===t.reason;}
root.innerHTML='<p class="activity-count">'+(i+1)+' / '+ts.length+' · '+t.title+'</p>'+body+'<p id="inheritEvidence"></p><div class="lab-actions"><button class="secondary" id="recordInherit">Record reasoning</button><button class="secondary" id="nextInherit">Next challenge →</button></div><p id="inheritProgress"></p>';
const status=()=>{$('#inheritEvidence').textContent=t.type==='compare'?t.cases.map((c,j)=>(v.seen.includes(j)?'✓ ':'○ ')+c[1]).join(' · '):w.inheritPassed.includes(t.id)?'Challenge recorded.':'';$('#inheritProgress').textContent=ts.filter(t=>w.inheritPassed.includes(t.id)).length+' / '+ts.length+' complete';};draw();status();
for(let el of root.querySelectorAll('select,input')){el.onchange=e=>{let id=e.target.id,val=e.target.value;if(id==='inheritDay'){v.day=val;save();draw();return;}if(id==='inheritCase'){if(val==='')return;v.case=Number(val);v.answer='';delete v.revealed;save();remount();return;}if(['inheritShoot','inheritRoot','inheritSeed','inheritBend'].includes(id)){v[id.slice(6).toLowerCase()]=val;draw();}else if(id==='inheritAnswer')v.answer=val;else if(id==='inheritNext')v.next=val;else if(id==='inheritNumber')v.number=val;else if(id==='inheritReason')v.reason=val;save();};if(el.tagName==='INPUT')el.oninput=e=>{if(e.target.id==='inheritDay'){v.day=e.target.value;draw();}else v.number=e.target.value;save();};}
if($('#revealInherit'))$('#revealInherit').onclick=()=>{if(v.answer===''){feedback('Choose a prediction first.',true);return;}v.revealed=v.case;save();draw();feedback(validInherit(t.cases[v.case],v.answer)?'Prediction agrees. Record the evidence.':t.cases[v.case][4],!validInherit(t.cases[v.case],v.answer));};
if($('#advanceInherit'))$('#advanceInherit').onclick=()=>{let n=advanceInherit(t.route,v.step,v.next);if(n===v.step){feedback(t.why+' Choose the next stage in order.',true);return;}v.step=n;v.next='';save();remount();};
$('#recordInherit').onclick=()=>{if(!valid()){feedback((t.type==='compare'?t.cases[v.case][4]:t.why)+' Check your evidence and reasoning.',true);return;}if(t.type==='compare'&&!v.seen.includes(v.case))v.seen.push(v.case);let finished=t.type!=='compare'||v.seen.length===t.cases.length;if(finished&&!w.inheritPassed.includes(t.id))w.inheritPassed.push(t.id);p.widgetDone=ts.every(t=>w.inheritPassed.includes(t.id));if(p.widgetDone)done();save();status();feedback(finished?'Challenge recorded.':'Recorded. Compare the remaining scenarios.');};$('#nextInherit').onclick=()=>{if(!w.inheritPassed.includes(t.id)){feedback('Complete this challenge first.',true);return;}w.inheritTask=ts[(i+1)%ts.length].id;save();remount();};}
